"# Шаг 2: Исправление ошибки merged cells в _write_nodes_table\n\n$filePath = \"C:\\eaip\\tools\\fill_energy_passport.py\"\n\n# Создаем бэкап\n$backupPath = \"$filePath.backup_step2\"\nCopy-Item $filePath $backupPath -Force\nWrite-Host \"Создан бэкап: $backupPath\" -ForegroundColor Green\n\n# Читаем файл\n$content = Get-Content $filePath -Raw\n\n# Заменяем строку 2175: ws.cell(row=current_row, column=col_idx).value = value\n# На: safe_cell_write(ws.cell(row=current_row, column=col_idx), value)\n$pattern1 = 'ws\.cell\(row=current_row, column=col_idx\)\.value = value'\n$replacement1 = 'safe_cell_write(ws.cell(row=current_row, column=col_idx), value)'\n\n# Заменяем строку 2180: ws.cell(row=current_row, column=col_idx).value = value\n# На: safe_cell_write(ws.cell(row=current_row, column=col_idx), value)\n$pattern2 = 'ws\.cell\(row=current_row, column=col_idx\)\.value = value'\n$replacement2 = 'safe_cell_write(ws.cell(row=current_row, column=col_idx), value)'\n\n# Применяем замены\n$newContent = $content -replace $pattern1, $replacement1\n$newContent = $newContent -replace $pattern2, $replacement2\n\n# Сохраняем изменения\nSet-Content $filePath $newContent -Encoding UTF8\n\n# Показываем diff\nWrite-Host \"`n=== DIFF ИЗМЕНЕНИЙ ===\" -ForegroundColor Green\ntry {\n    git diff $backupPath $filePath\n} catch {\n    Write-Host \"Git не доступен, показываем изменения вручную...\" -ForegroundColor Yellow\n    \n    # Показываем измененные строки\n    $oldLines = Get-Content $backupPath\n    $newLines = Get-Content $filePath\n    \n    Write-Host \"`nИзменения в строке 2175:\" -ForegroundColor Cyan\n    Write-Host \"Было: $($oldLines[2174])\"\n    Write-Host \"Стало: $($newLines[2174])\"\n    \n    Write-Host \"`nИзменения в строке 2180:\" -ForegroundColor Cyan\n    Write-Host \"Было: $($oldLines[2179])\"\n    Write-Host \"Стало: $($newLines[2179])\"\n}\n\nWrite-Host \"`n=== ПРОВЕРКА ===\" -ForegroundColor Yellow\nWrite-Host \"1. Проверьте diff выше\"\nWrite-Host \"2. Запустите тест: test_passport_generation_with_metin_template\"\nWrite-Host \"3. Если все работает, удалите бэкап: Remove-Item '$backupPath'\"\n\nWrite-Host \"`n=== ЧТО ИЗМЕНИЛОСЬ ===\" -ForegroundColor Green\nWrite-Host \"- Строка 2175: Используется safe_cell_write() вместо прямого присваивания\"\nWrite-Host \"- Строка 2180: Используется safe_cell_write() вместо прямого присваивания\"\nWrite-Host \"- safe_cell_write() проверяет merged cells и пропускает их\""